func resourceDiscoveryEngineUserLicenseEncoder(d *schema.ResourceData, meta interface{}, obj map[string]interface{}) (map[string]interface{}, error) {
	userLicense := make(map[string]interface{})

	if v, ok := obj["userPrincipal"].(string); ok && v != "" {
		userLicense["userPrincipal"] = v
	} else if v, ok := d.Get("user_principal").(string); ok && v != "" {
		userLicense["userPrincipal"] = v
	}
	if v, ok := obj["licenseConfig"].(string); ok && v != "" {
		userLicense["licenseConfig"] = v
	}
	if v, ok := obj["userProfile"].(string); ok && v != "" {
		userLicense["userProfile"] = v
	}

	// On Create and Update, if license_config is omitted or cleared, keep the
	// unassigned user license record in the UserStore (NO_LICENSE) rather than
	// deleting the row from Spanner. Row deletion is controlled by
	// delete_unassigned_user_licenses during Delete.
	deleteUnassigned := false
	if lc, ok := userLicense["licenseConfig"].(string); ok && lc != "" {
		if v, ok := d.Get("delete_unassigned_user_licenses").(bool); ok {
			deleteUnassigned = v
		}
	}

	req := map[string]interface{}{
		"inlineSource": map[string]interface{}{
			"userLicenses": []interface{}{userLicense},
		},
		"deleteUnassignedUserLicenses": deleteUnassigned,
	}
	return req, nil
}

func flattenNestedDiscoveryEngineUserLicense(d *schema.ResourceData, meta interface{}, res map[string]interface{}) (map[string]interface{}, error) {
	var v interface{}
	var ok bool

	v, ok = res["userLicenses"]
	if !ok || v == nil {
		return nil, nil
	}

	switch v.(type) {
	case []interface{}:
		break
	case map[string]interface{}:
		// Construct list out of single nested resource
		v = []interface{}{v}
	default:
		return nil, fmt.Errorf("expected list or map for value userLicenses. Actual value: %v", v)
	}

	_, item, err := resourceDiscoveryEngineUserLicenseFindNestedObjectInList(d, meta, v.([]interface{}))
	if err != nil {
		return nil, err
	}
	return item, nil
}

func resourceDiscoveryEngineUserLicenseFindNestedObjectInList(d *schema.ResourceData, meta interface{}, items []interface{}) (index int, item map[string]interface{}, err error) {
	expectedUserPrincipal, err := expandNestedDiscoveryEngineUserLicenseUserPrincipal(d.Get("user_principal"), d, meta.(*transport_tpg.Config))
	if err != nil {
		return -1, nil, err
	}
	expectedFlattenedUserPrincipal := flattenNestedDiscoveryEngineUserLicenseUserPrincipal(expectedUserPrincipal, d, meta.(*transport_tpg.Config))

	// Search list for this resource.
	for idx, itemRaw := range items {
		if itemRaw == nil {
			continue
		}
		item := itemRaw.(map[string]interface{})

		itemUserPrincipal := flattenNestedDiscoveryEngineUserLicenseUserPrincipal(item["userPrincipal"], d, meta.(*transport_tpg.Config))
		// IsEmptyValue check so that if one is nil and the other is "", that's considered a match
		if !(tpgresource.IsEmptyValue(reflect.ValueOf(itemUserPrincipal)) && tpgresource.IsEmptyValue(reflect.ValueOf(expectedFlattenedUserPrincipal))) && !reflect.DeepEqual(itemUserPrincipal, expectedFlattenedUserPrincipal) {
			log.Printf("[DEBUG] Skipping item with userPrincipal= %#v, looking for %#v)", itemUserPrincipal, expectedFlattenedUserPrincipal)
			continue
		}
		log.Printf("[DEBUG] Found item for resource %q: %#v)", d.Id(), item)
		return idx, item, nil
	}
	return -1, nil, nil
}

func ResourceDiscoveryEngineUserLicenseFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("user_principal", flattenNestedDiscoveryEngineUserLicenseUserPrincipal(res["userPrincipal"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}
	if err = d.Set("license_config", flattenNestedDiscoveryEngineUserLicenseLicenseConfig(res["licenseConfig"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}
	if err = d.Set("user_profile", flattenNestedDiscoveryEngineUserLicenseUserProfile(res["userProfile"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}
	if err = d.Set("license_assignment_state", flattenNestedDiscoveryEngineUserLicenseLicenseAssignmentState(res["licenseAssignmentState"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}
	if err = d.Set("create_time", flattenNestedDiscoveryEngineUserLicenseCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}
	if err = d.Set("update_time", flattenNestedDiscoveryEngineUserLicenseUpdateTime(res["updateTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}
	if err = d.Set("last_login_time", flattenNestedDiscoveryEngineUserLicenseLastLoginTime(res["lastLoginTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading UserLicense: %s", err)
	}

	return nil
}
